request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-008

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "DIAGNOSES_FAILURE_CAUSE",
    "definition": "The reasoning assigns a specific causal mechanism to a failure or error reported in an observation, explaining how the failure arose rather than merely restating the error text.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node explaining the cause or mechanism of the failure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the error or unsuccessful outcome."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, non-zero exit status, or otherwise unsuccessful outcome.",
      "The reasoning identifies a specific cause or mechanism responsible for that failure, going beyond the literal error message.",
      "The stated cause is consistent with the facts reported in the observation."
    ],
    "exclusion_conditions": [
      "The reasoning merely notes that a failure occurred.",
      "The reasoning proposes a retry without explaining the cause.",
      "The reasoning only repeats or paraphrases the error message without explaining it.",
      "The stated cause contradicts the observation's reported facts.",
      "The observation does not report a failure or error."
    ]
  },
  {
    "name": "ATTRIBUTES_FAILURE_TO_TEST_HARNESS_ARTIFACT",
    "definition": "The reasoning classifies a failure observed during the agent's own verification, probe, or simulated execution as originating in the checking environment — its tooling, missing modules, instrumentation, or simulated conditions — rather than as a defect in the artifact being checked, and treats the artifact's own validity or structure as unaffected.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that reinterprets the observed failure as originating in the checking environment rather than in the artifact."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure whose origin is being classified."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure that occurred during the agent's own verification, probe, or simulation procedure.",
      "The reasoning states that the failure originates in the checking environment, such as missing tooling or modules, test instrumentation, simulated inputs, ad hoc invocation, or missing test-side configuration, rather than in the artifact being checked.",
      "The reasoning treats the artifact's own validity, structure, or behavior as unaffected by that failure, either by affirming this directly or by contrasting the checking conditions with the conditions under which the artifact will actually be used."
    ],
    "exclusion_conditions": [
      "The reasoning treats the failure as a genuine defect in the delivered artifact, configuration, or state.",
      "The reasoning reports the failure without interpreting where it originated.",
      "The reasoning attributes the failure to the artifact itself or to the conditions under which the artifact will actually be used.",
      "No indication is given that the artifact's own validity is preserved or that the checking conditions differ from actual-use conditions."
    ]
  },
  {
    "name": "DETECTS_OBSERVED_DATA_INCONSISTENCY",
    "definition": "The reasoning identifies an explicit discrepancy between the content of an observation and what its labeling, structure, or surrounding context led the agent to expect, and states that discrepancy as a finding.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning text that names the mismatch between observed content and the expectation."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation whose content contains the unexpected or inconsistent element."
      }
    ],
    "assertion_conditions": [
      "The reasoning states what was expected and what was actually observed.",
      "The inconsistency is attributable to identifiable content in the observation."
    ],
    "exclusion_conditions": [
      "The reasoning only summarizes the observation without comparing it to an expectation.",
      "The claimed mismatch is between two reasoning statements rather than traced to the observation's content.",
      "No expectation about the observation's content is articulated."
    ]
  },
  {
    "name": "RECOGNIZES_ANOMALY_IN_OBSERVATION",
    "definition": "The reasoning identifies a condition reported by an observation as unexpected, contradictory, or otherwise deviating from the anticipated state, and treats it as something requiring explanation, investigation, or handling because it bears on the intended outcome.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that flags the reported condition as unexpected and states its significance."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the warning, conflict, deviation, or otherwise unanticipated condition."
      }
    ],
    "assertion_conditions": [
      "The observation reports a warning, conflict, deviation, or unanticipated condition rather than the expected clean result.",
      "The reasoning characterizes that condition as unexpected, contradictory, or in need of investigation or handling.",
      "The reasoning indicates why the condition matters for the intended outcome."
    ],
    "exclusion_conditions": [
      "The observation matches the expected outcome and the reasoning treats it as ordinary success.",
      "The reasoning merely quotes the reported condition without judging it unexpected or consequential.",
      "The anomaly is explained with an identified benign origin and judged harmless to the required behavior.",
      "The deviation is only inferred later, without the reasoning connecting it to the observation."
    ]
  },
  {
    "name": "INTERPRETS_ADVERSE_OBSERVATION_AS_BENIGN_OR_EXPECTED",
    "definition": "The reasoning interprets an observation that reports an error, missing content, residual artifact, unexpected entry, or other adverse or unexpected result as benign or expected, by explaining its cause or why it does not indicate a defect, and judges it not to impair required behavior or as consistent with correct progress.",
    "parameters": [
      {
        "name": "result_reasoning",
        "type": "reasoning",
        "description": "The reasoning explaining why the adverse or unexpected result is benign or expected at the current stage."
      },
      {
        "name": "negative_observation",
        "type": "observation",
        "description": "The observation containing the error response, missing content, residual artifact, unexpected entry, or other adverse or unexpected result being interpreted."
      }
    ],
    "assertion_conditions": [
      "The observation shows an error response, missing resource, empty content, residual artifact, unexpected entry, nonzero status, or other adverse or unexpected result.",
      "The reasoning explicitly explains why that result is expected, benign, or caused by a non-defect condition, such as a current intermediate stage, test instrumentation, or harmless residual state.",
      "The reasoning judges the result as not impairing required behavior or as consistent with correct progress, supported by or consistent with other evidence."
    ],
    "exclusion_conditions": [
      "The reasoning treats the adverse or unexpected result as a failure requiring correction.",
      "The reasoning ignores or merely repeats the result without interpreting it as benign or expected.",
      "The observation reports a positive or unambiguously successful result.",
      "The result is dismissed without any stated cause, or while contradicting evidence shows the required behavior is impaired.",
      "The error indication shows that a required output is missing or that the task cannot be completed as required."
    ]
  },
  {
    "name": "DISCARDS_EVIDENCE_FROM_FAILED_OPERATION",
    "definition": "The reasoning judges a value or result recorded in an observation to be unusable or meaningless as evidence because the operation that produced it failed, thereby excluding that data from subsequent conclusions.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node explaining why the reported result is invalid evidence given the failure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting both the failure of the underlying operation and the derived value or result in question."
      }
    ],
    "assertion_conditions": [
      "The observation indicates that the underlying operation failed or did not execute as intended.",
      "The observation also reports an accompanying measurement or result that would otherwise be informative.",
      "The reasoning explicitly states that the accompanying value or result is meaningless, invalid, or unusable because of that failure."
    ],
    "exclusion_conditions": [
      "The reasoning accepts or relies on the reported value as valid evidence.",
      "The observation shows no failure that would undermine the reported value.",
      "The reasoning notes the failure but says nothing about the validity of the accompanying value."
    ]
  },
  {
    "name": "RESOLVES_AMBIGUITY_BY_OBSERVED_BEHAVIOR",
    "definition": "The reasoning identifies an ambiguity or conflicting expectation about how a requirement, tool, or system will actually behave, and resolves it by treating the concrete behavior reported in an observation as the authoritative reference fact, adjusting its interpretation or plan to match that observed behavior.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text that names the ambiguity or conflicting expectation and adopts the observed behavior as authoritative."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the concrete behavior that settles the ambiguity."
      }
    ],
    "assertion_conditions": [
      "The reasoning explicitly identifies a specific ambiguity, alternative reading, or conflict between expectations about how something will behave.",
      "The reasoning explicitly adopts the concrete outcome reported in the observation as the authoritative fact, rather than continuing to settle the matter by speculation.",
      "The reasoning adjusts its interpretation, decision, or plan to conform to that observed behavior."
    ],
    "exclusion_conditions": [
      "The reasoning merely uses the observation as general supporting evidence without any identified ambiguity or conflicting expectation.",
      "The observation does not concern the ambiguity in question.",
      "The ambiguity is resolved by an assumed or conventional interpretation rather than by deferring to observed behavior.",
      "The reasoning continues to speculate about the requirement or behavior instead of deferring to what was observed."
    ]
  },
  {
    "name": "EXPLAINS_ANOMALOUS_RESULT_WITH_CAUSAL_HYPOTHESIS",
    "definition": "The reasoning accounts for an observation whose reported outcome deviates from what the agent anticipated by identifying a causal or mechanistic process that would produce that outcome, instead of merely noting or restating the deviation.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text constructing the causal or mechanistic explanation for the unexpected result."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The tool result whose reported outcome deviates from what the agent anticipated."
      }
    ],
    "assertion_conditions": [
      "The observation reports an outcome that differs from the outcome the agent anticipated, for example uniform successes where rejections were expected, an unexpected quantity or timing, or a result that contradicts an assumed behavior.",
      "The reasoning identifies a concrete mechanism or process (such as pacing, serialization, request queueing/delay, per-invocation overhead, or an ignored or absent capability) that would produce exactly that deviation.",
      "The reasoning presents that mechanism as the reason this specific observed outcome occurred, rather than as an unrelated general remark or as a restatement of the output."
    ],
    "exclusion_conditions": [
      "The observation matches the expectation, so no deviation needs explaining.",
      "The reasoning only repeats the observed result, or expresses surprise, without proposing any mechanism.",
      "The proposed mechanism is incompatible with the content of the observation.",
      "The observation reports an outright error and the reasoning merely repeats or paraphrases the error text without explaining the causal process."
    ]
  },
  {
    "name": "ADAPTS_APPROACH_AFTER_FAILURE",
    "definition": "The reasoning proposes a changed or alternative course of action in response to a failure or negative outcome reported by the observation, aiming to overcome the condition that caused the failure.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text describing the revised or alternative course of action."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting the failure or negative outcome that motivates the change."
      }
    ],
    "assertion_conditions": [
      "The observation reports a failure, rejection, error, or other negative outcome.",
      "The reasoning describes a changed approach, such as a different method, an added preparatory step, or an alternative parameterization, relative to what failed.",
      "The proposed change is presented as a response to that negative outcome."
    ],
    "exclusion_conditions": [
      "The reasoning repeats the same approach unchanged.",
      "No failure or negative outcome is present in the observation.",
      "The proposed change is unrelated to the reported failure."
    ]
  }
]

